def fill_assignment_dates(apps, schema_editor):
    """Tasks that already have an assignee were given out when they were created. Nothing else is touched."""
    Task = apps.get_model("crm", "Task")
    Task.objects.filter(assignee__isnull=False, assigned_at__isnull=True).update(assigned_at=models.F("created_at"))


